def calculate_f(x, y, z, a, b, c):
    term1 = abs(x + y - a - b)
    term2 = abs(y + z - b - c)
    term3 = abs(z + x - c - a)
    return term1 + term2 + term3

triples = [(1, 1, 1), (1, 2, 3), (9, 9, 9), (0, 1, 2)]
queries = [(0, 0, 0), (9, 0, 0), (0, 9, 0)]

results = {}
for i, triple in enumerate(triples):
    x, y, z = triple
    results[triple] = {}
    for j, query in enumerate(queries):
        a, b, c = query
        f_val = calculate_f(x, y, z, a, b, c)
        results[triple][f"Q{j+1} ({a},{b},{c})"] = f_val

for triple, values in results.items():
    print(f"Triple {triple}: {values}")

